var i=164;var a=`164-stock-clarity-skimming-and-impurity-removal`;var r=`161`;var s={en:`Stock Clarity, Skimming, and Impurity Removal`,ua:`Прозорість бульйону та видалення піни й домішок`};var o={short:`Clear stock requires limiting suspended particles, foam, and dispersed fat during cooking and straining. Skimming and gentle simmering improve appearance, while true consommé clarification is a separate, more demanding process.`,sections:[{title:`Core idea`,text:`Surface scum contains coagulated proteins and impurities. Rapid boiling breaks particles apart and distributes fat; this can produce a cloudy yet edible stock rather than a clear one.`},{title:`Science`,text:`Heating causes some proteins to coagulate into visible particles. Slow convection brings them toward the surface, where they can be skimmed. Fine filtration removes more solids; chilling makes a fat cap easier to remove.`},{title:`How to apply`,text:`Start with suitable ingredients and water, heat gradually, skim without stirring the whole pot, then hold a gentle simmer. Ladle through a fine sieve or clean straining cloth without squeezing solids. Cool rapidly before refrigerating.`},{title:`Practical experiment`,text:`Cook identical small batches at a light simmer and a vigorous boil. Filter them similarly and compare turbidity in identical transparent glasses under strong side lighting.`},{title:`Common mistakes`,text:`Treating foam as a measure of food safety is incorrect; removing it improves clarity, not necessarily microbiological safety. Avoid squeezing vegetable mash through the strainer when clear stock is the goal.`},{title:`Related theories`,text:`161, 162, 166.`}]};var n={short:`Для прозорого бульйону слід обмежувати завислі частинки, піну й розподілений у рідині жир. Знімання піни та делікатне томління покращують вигляд, а освітлення консоме є окремою складнішою технологією.`,sections:[{title:`Суть`,text:`Піна на поверхні містить згорнуті білки та інші частинки. Сильне кипіння подрібнює їх і розподіляє жир у рідині, тому бульйон стає каламутним, хоча це не завжди робить його непридатним.`},{title:`Наука`,text:`Нагрівання коагулює частину білків у видимі пластівці. Повільні конвекційні потоки піднімають їх до поверхні, звідки їх можна зняти. Дрібне проціджування видаляє залишкові частинки, а охолодження полегшує знімання жирового шару.`},{title:`Як застосувати`,text:`Поступово нагрівайте підготовлені компоненти, регулярно знімайте піну без активного перемішування та підтримуйте слабке кипіння. Процідіть через дрібне сито чи чисту тканину, не відтискаючи тверді частини. Швидко охолодіть.`},{title:`Практичний дослід`,text:`Приготуйте дві однакові основи, одну при слабкому кипінні, другу бурхливо. Однаково процідіть, налийте у склянки й порівняйте каламутність за бокового освітлення.`},{title:`Поширені помилки`,text:`Зняття піни покращує прозорість, але не гарантує мікробіологічної безпеки. Якщо потрібна прозора основа, не відтискайте овочеве пюре через сито.`},{title:`Пов’язані теорії`,text:`161, 162, 166.`}]};var l=[161,162,166];var c=`References / Джерела`;var m=[`https://www.theculinarypro.com/stocks-soups-and-sauces-1`,`https://www.theculinarypro.com/soups`];var d={id:164,slug:a,group:`161`,title:s,en:o,ua:n,related:l,referenceTitle:c,references:m};export{d as default,o as en,r as group,i as id,c as referenceTitle,m as references,l as related,a as slug,s as title,n as ua};